const spreadsheetId = $('Set Variables').first().json.spreadsheetId;
const dateToday = $('Set Variables').first().json.date_today;
const managerEmail = $('Set Variables').first().json.manager_email || '';
const fileInfo = $json;

// Extract domain from spreadsheet name
const name = fileInfo.name || '';
let domain = '';
const domainMatch = name.match(/[-–—]\s*([a-zA-Z0-9][a-zA-Z0-9-]*\.[a-zA-Z]{2,})\s*[-–—]/)
  || name.match(/([a-zA-Z0-9][a-zA-Z0-9-]*\.[a-zA-Z]{2,})/);
if (domainMatch) {
  domain = domainMatch[1];
}

// Get parent folder ID (fallback if no manager_email)
const folderId = fileInfo.parents?.[0] || '';

return [{
  json: {
    spreadsheetId,
    domain,
    folderId,
    dateToday,
    spreadsheetName: name,
    managerEmail
  }
}];

const domain = $('Extract Domain & Folder').first().json.domain;
const spreadsheetId = $('Extract Domain & Folder').first().json.spreadsheetId;
const folderId = $('Extract Domain & Folder').first().json.folderId;
const dateToday = $('Extract Domain & Folder').first().json.dateToday;

const valueRanges = $json.valueRanges || [];

function parseSheet(values) {
  if (!values || values.length < 2) return { headers: [], rows: [], stats: {} };
  const headers = values[0];
  const rows = values.slice(1);
  return { headers, rows, count: rows.length };
}

function chunkArray(arr, size) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
}

function summarizeData(data, topN = 100) {
  const top = data.rows.slice(0, topN);
  const stats = {
    totalRows: data.rows.length,
    headers: data.headers
  };
  return { top, stats, headers: data.headers };
}

// Parse all 6 sheets
const sheets = {
  organic: parseSheet(valueRanges[0]?.values),
  linkProfile: parseSheet(valueRanges[1]?.values),
  topPagesByLinks: parseSheet(valueRanges[2]?.values),
  behavioral: parseSheet(valueRanges[3]?.values),
  keywords: parseSheet(valueRanges[4]?.values),
  trafficPages: parseSheet(valueRanges[5]?.values)
};

// Prepare data for each agent
const agent1Data = {
  name: 'Органічний трафік',
  data: summarizeData(sheets.organic, 50)
};

const agent2Data = {
  name: 'Посилальний профіль',
  data: summarizeData(sheets.linkProfile, 50)
};

const agent3Data = {
  name: 'Топ сторінки за посиланнями',
  data: summarizeData(sheets.topPagesByLinks, 100)
};

const agent4Data = {
  name: 'Поведінкові метрики',
  data: summarizeData(sheets.behavioral, 50)
};

// Keywords - chunk by 500 if large
const keywordsChunks = sheets.keywords.rows.length > 500 
  ? chunkArray(sheets.keywords.rows, 500).slice(0, 3) // Max 3 chunks for cost
  : [sheets.keywords.rows];

const agent5Data = {
  name: 'Ключові фрази',
  data: {
    headers: sheets.keywords.headers,
    chunks: keywordsChunks.map((chunk, i) => ({
      chunkNum: i + 1,
      totalChunks: keywordsChunks.length,
      rows: chunk.slice(0, 200) // Limit each chunk
    })),
    stats: {
      totalKeywords: sheets.keywords.rows.length
    }
  }
};

const agent6Data = {
  name: 'Трафікогенеруючі сторінки',
  data: summarizeData(sheets.trafficPages, 100)
};

return [{
  json: {
    domain,
    spreadsheetId,
    folderId,
    dateToday,
    agent1Data,
    agent2Data,
    agent3Data,
    agent4Data,
    agent5Data,
    agent6Data
  }
}];

const items = $input.all();

const domain = $('Extract Domain & Folder').first().json.domain;
const dateToday = $('Extract Domain & Folder').first().json.dateToday || $('Extract Domain & Folder').first().json.date_today;
const folderId = $('Extract Domain & Folder').first().json.folderId;
const spreadsheetId = $('Extract Domain & Folder').first().json.spreadsheetId;

// Collect all agent responses - items arrive in order by input index (0-5)
const sections = [];
for (const item of items) {
  const content = item.json.message?.content || item.json.content || item.json.text || item.json.output || '';
  sections.push(content);
}

// Ensure we have exactly 6 sections
while (sections.length < 6) {
  sections.push('[Дані відсутні]');
}

return [{
  json: {
    domain,
    dateToday,
    folderId,
    spreadsheetId,
    section1: sections[0],
    section2: sections[1],
    section3: sections[2],
    section4: sections[3],
    section5: sections[4],
    section6: sections[5],
    sectionsCount: items.length,
    allSections: sections.filter(s => s && s !== '[Дані відсутні]').join('\n\n---\n\n')
  }
}];

const domain = $('Extract Domain & Folder').first().json.domain;
const dateToday = $('Extract Domain & Folder').first().json.dateToday || $('Extract Domain & Folder').first().json.date_today;
const folderId = $('Extract Domain & Folder').first().json.folderId;

const section1 = $('Collect Sections').first().json.section1 || '';
const section2 = $('Collect Sections').first().json.section2 || '';
const section3 = $('Collect Sections').first().json.section3 || '';
const section4 = $('Collect Sections').first().json.section4 || '';
const section5 = $('Collect Sections').first().json.section5 || '';
const section6 = $('Collect Sections').first().json.section6 || '';
const finalSummary = $json.message?.content || $json.content || $json.text || '';

function cleanMarkdown(text) {
  return text
    .replace(/^#{1,4}\s*/gm, '')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/^---+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// ── TABLE EXTRACTION ──
// Global table counter across all sections
let tableCounter = 0;
const allTables = [];

function extractTables(text) {
  const tableRegex = /<<<TABLE>>>\s*([\s\S]*?)\s*<<<TABLE_END>>>/g;
  const result = text.replace(tableRegex, (match, jsonStr) => {
    try {
      // Clean the JSON string (remove potential markdown artifacts)
      let cleaned = jsonStr.trim();
      // Try to fix common JSON issues from LLM output
      if (!cleaned.startsWith('{')) {
        const braceStart = cleaned.indexOf('{');
        if (braceStart >= 0) cleaned = cleaned.substring(braceStart);
      }
      const lastBrace = cleaned.lastIndexOf('}');
      if (lastBrace >= 0) cleaned = cleaned.substring(0, lastBrace + 1);

      const tableData = JSON.parse(cleaned);
      const headers = tableData.headers || [];
      const rows = tableData.rows || [];

      if (headers.length === 0) return match; // Invalid table

      const idx = tableCounter++;
      const placeholder = '{{TBL:' + idx + '}}';
      allTables.push({
        index: idx,
        placeholder: placeholder,
        headers: headers,
        rows: rows
      });
      return '\n' + placeholder + '\n';
    } catch(e) {
      // If JSON parsing fails, also try to catch markdown tables that slipped through
      return match;
    }
  });

  // Also catch markdown tables (|---|) and convert them
  const mdTableRegex = /(?:^|\n)((?:\|[^\n]+\|\n)+)/g;
  const result2 = result.replace(mdTableRegex, (match, tableBlock) => {
    const lines = tableBlock.trim().split('\n').filter(l => l.trim());
    if (lines.length < 2) return match;

    // Check if second line is a separator (|---|---|)
    const sepIdx = lines.findIndex(l => /^\|[\s\-:|]+\|$/.test(l.trim()));
    if (sepIdx < 0) return match;

    const headerLine = lines[sepIdx - 1] || lines[0];
    const headers = headerLine.split('|').filter(c => c.trim()).map(c => c.trim());
    const dataLines = lines.slice(sepIdx + 1);
    const rows = dataLines.map(l =>
      l.split('|').filter(c => c.trim()).map(c => c.trim())
    ).filter(r => r.length > 0);

    if (headers.length === 0 || rows.length === 0) return match;

    const idx = tableCounter++;
    const placeholder = '{{TBL:' + idx + '}}';
    allTables.push({
      index: idx,
      placeholder: placeholder,
      headers: headers,
      rows: rows
    });
    return '\n' + placeholder + '\n';
  });

  return result2;
}

// ── SUBHEADING DETECTION ──
function findSubheadings(text, startPos) {
  const ranges = [];
  const lines = text.split('\n');
  let currentPos = startPos;

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.length >= 3 &&
        /[А-ЯЇІЄҐA-Z]/.test(trimmed) &&
        !/[а-яїієґa-z]/.test(trimmed) &&
        !trimmed.startsWith('━') &&
        !trimmed.match(/^\d+\.$/) &&
        !trimmed.startsWith('{{TBL:') &&
        trimmed.length < 60) {
      ranges.push({
        start: currentPos,
        end: currentPos + line.length,
        type: 'subheading',
        text: trimmed
      });
    }
    currentPos += line.length + 1;
  }
  return ranges;
}

// ── PROCESS SECTIONS — extract tables BEFORE cleaning markdown ──
const rawSections = [finalSummary, section1, section2, section3, section4, section5, section6];
const processedSections = rawSections.map(s => cleanMarkdown(extractTables(s)));

const formatRanges = [];
let content = '';
let pos = 1;

// ══════════════════════════════════════════════════════════════
// TITLE PAGE
// ══════════════════════════════════════════════════════════════

const spacer1 = '\n\n\n\n\n';
content += spacer1; pos += spacer1.length;

const mainTitle = 'SEO АУДИТ';
formatRanges.push({ start: pos, end: pos + mainTitle.length, type: 'mainTitle' });
content += mainTitle + '\n\n'; pos += mainTitle.length + 2;

const domainTitle = domain.toUpperCase();
formatRanges.push({ start: pos, end: pos + domainTitle.length, type: 'domainTitle' });
content += domainTitle + '\n\n\n'; pos += domainTitle.length + 3;

const dateStr = dateToday;
formatRanges.push({ start: pos, end: pos + dateStr.length, type: 'dateText' });
content += dateStr + '\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n'; pos += dateStr.length + 15;

// ══════════════════════════════════════════════════════════════
// TABLE OF CONTENTS
// ══════════════════════════════════════════════════════════════

const tocHeader = 'ЗМІСТ';
formatRanges.push({ start: pos, end: pos + tocHeader.length, type: 'tocHeader' });
content += tocHeader + '\n\n'; pos += tocHeader.length + 2;

const tocLine = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━';
formatRanges.push({ start: pos, end: pos + tocLine.length, type: 'tocLine' });
content += tocLine + '\n\n'; pos += tocLine.length + 2;

const tocItems = [
  { num: '01', title: 'Executive Summary' },
  { num: '02', title: 'Органічний трафік' },
  { num: '03', title: 'Посилальний профіль' },
  { num: '04', title: 'Топ сторінки за посиланнями' },
  { num: '05', title: 'Поведінкові метрики' },
  { num: '06', title: 'Ключові фрази' },
  { num: '07', title: 'Трафікогенеруючі сторінки' }
];

for (const item of tocItems) {
  const tocItemText = `     ${item.num}     ${item.title}`;
  formatRanges.push({ start: pos, end: pos + 7, type: 'tocNum' });
  content += tocItemText + '\n\n'; pos += tocItemText.length + 2;
}

content += '\n\n\n\n\n\n\n\n\n\n\n\n'; pos += 12;

// ══════════════════════════════════════════════════════════════
// SECTIONS
// ══════════════════════════════════════════════════════════════

const sections = [
  { num: '01', title: 'EXECUTIVE SUMMARY', content: processedSections[0], isExec: true },
  { num: '02', title: 'ОРГАНІЧНИЙ ТРАФІК', content: processedSections[1] },
  { num: '03', title: 'ПОСИЛАЛЬНИЙ ПРОФІЛЬ', content: processedSections[2] },
  { num: '04', title: 'ТОП СТОРІНКИ ЗА ПОСИЛАННЯМИ', content: processedSections[3] },
  { num: '05', title: 'ПОВЕДІНКОВІ МЕТРИКИ', content: processedSections[4] },
  { num: '06', title: 'КЛЮЧОВІ ФРАЗИ', content: processedSections[5] },
  { num: '07', title: 'ТРАФІКОГЕНЕРУЮЧІ СТОРІНКИ', content: processedSections[6] }
];

for (const section of sections) {
  const numText = section.num;
  formatRanges.push({ start: pos, end: pos + numText.length, type: 'sectionNum' });
  content += numText + '\n'; pos += numText.length + 1;

  const titleText = section.title;
  formatRanges.push({ start: pos, end: pos + titleText.length, type: section.isExec ? 'execTitle' : 'sectionTitle' });
  content += titleText + '\n'; pos += titleText.length + 1;

  const underline = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━';
  formatRanges.push({ start: pos, end: pos + underline.length, type: 'sectionLine' });
  content += underline + '\n\n'; pos += underline.length + 2;

  const sectionContent = section.content + '\n\n\n\n';
  const subheadings = findSubheadings(sectionContent, pos);
  formatRanges.push(...subheadings);

  content += sectionContent; pos += sectionContent.length;
}

// ══════════════════════════════════════════════════════════════
// FOOTER
// ══════════════════════════════════════════════════════════════

const footerLine = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━';
formatRanges.push({ start: pos, end: pos + footerLine.length, type: 'footerLine' });
content += footerLine + '\n\n'; pos += footerLine.length + 2;

const footerText = `Конфіденційний документ  •  ${domain}  •  ${dateToday}`;
formatRanges.push({ start: pos, end: pos + footerText.length, type: 'footerText' });
content += footerText + '\n';

return [{
  json: {
    domain,
    dateToday,
    folderId,
    docTitle: `SEO Аудит │ ${domain} │ ${dateToday}`,
    docContent: content,
    formatRanges,
    tables: allTables
  }
}];

const docId = $('Create Google Doc').first().json.documentId;
const formatRanges = $('Prepare Document').first().json.formatRanges || [];
const docContent = $('Prepare Document').first().json.docContent || '';

// Premium color palette
const colors = {
  navy: { red: 0.1, green: 0.15, blue: 0.3 },
  darkBlue: { red: 0.15, green: 0.25, blue: 0.45 },
  gold: { red: 0.75, green: 0.6, blue: 0.2 },
  gray: { red: 0.4, green: 0.4, blue: 0.4 },
  lightGray: { red: 0.6, green: 0.6, blue: 0.6 },
  bodyText: { red: 0.15, green: 0.15, blue: 0.15 }
};

const requests = [];

// ═══════════════════════════════════════════════════════════════
// STEP 1: Apply PROFESSIONAL body text style to ENTIRE document
// ═══════════════════════════════════════════════════════════════
const docLength = docContent.length;
if (docLength > 1) {
  // Body text style - professional and readable
  requests.push({
    updateTextStyle: {
      range: { startIndex: 1, endIndex: docLength },
      textStyle: {
        fontSize: { magnitude: 11, unit: 'PT' },
        foregroundColor: { color: { rgbColor: colors.bodyText } },
        weightedFontFamily: { fontFamily: 'Open Sans', weight: 400 }
      },
      fields: 'fontSize,foregroundColor,weightedFontFamily'
    }
  });

  // Paragraph style - professional spacing and alignment
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: 1, endIndex: docLength },
      paragraphStyle: {
        lineSpacing: 150,
        spaceAbove: { magnitude: 4, unit: 'PT' },
        spaceBelow: { magnitude: 8, unit: 'PT' },
        alignment: 'JUSTIFIED',
        indentFirstLine: { magnitude: 0, unit: 'PT' },
        indentStart: { magnitude: 0, unit: 'PT' }
      },
      fields: 'lineSpacing,spaceAbove,spaceBelow,alignment,indentFirstLine,indentStart'
    }
  });
}

// ═══════════════════════════════════════════════════════════════
// STEP 2: Apply specific formatting for headers, titles, etc.
// ═══════════════════════════════════════════════════════════════
for (const range of formatRanges) {
  const r = { startIndex: range.start, endIndex: range.end };

  switch (range.type) {
    case 'mainTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 36, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.navy } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 700 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'CENTER', 
            spaceAbove: { magnitude: 0, unit: 'PT' }, 
            spaceBelow: { magnitude: 12, unit: 'PT' },
            lineSpacing: 100
          },
          fields: 'alignment,spaceAbove,spaceBelow,lineSpacing'
        }
      });
      break;

    case 'domainTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 28, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.gold } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { alignment: 'CENTER', lineSpacing: 100 },
          fields: 'alignment,lineSpacing'
        }
      });
      break;

    case 'dateText':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            fontSize: { magnitude: 14, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.gray } },
            weightedFontFamily: { fontFamily: 'Open Sans', weight: 400 }
          },
          fields: 'fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { alignment: 'CENTER', lineSpacing: 100 },
          fields: 'alignment,lineSpacing'
        }
      });
      break;

    case 'tocHeader':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 18, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.navy } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 700 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { alignment: 'START', lineSpacing: 100 },
          fields: 'alignment,lineSpacing'
        }
      });
      break;

    case 'tocLine':
    case 'sectionLine':
    case 'footerLine':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            foregroundColor: { color: { rgbColor: colors.gold } },
            fontSize: { magnitude: 10, unit: 'PT' }
          },
          fields: 'foregroundColor,fontSize'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            lineSpacing: 100,
            spaceAbove: { magnitude: 0, unit: 'PT' },
            spaceBelow: { magnitude: 12, unit: 'PT' }
          },
          fields: 'lineSpacing,spaceAbove,spaceBelow'
        }
      });
      break;

    case 'tocNum':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 11, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.darkBlue } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      break;

    case 'sectionNum':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 48, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.gold } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 700 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceAbove: { magnitude: 24, unit: 'PT' },
            spaceBelow: { magnitude: 0, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
        }
      });
      break;

    case 'execTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 22, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.navy } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 700 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceBelow: { magnitude: 4, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceBelow'
        }
      });
      break;

    case 'sectionTitle':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 18, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.darkBlue } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'START',
            lineSpacing: 100,
            spaceBelow: { magnitude: 4, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceBelow'
        }
      });
      break;

    case 'subheading':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            bold: true,
            fontSize: { magnitude: 12, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.darkBlue } },
            weightedFontFamily: { fontFamily: 'Montserrat', weight: 600 }
          },
          fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: {
            alignment: 'START',
            lineSpacing: 100,
            spaceAbove: { magnitude: 18, unit: 'PT' },
            spaceBelow: { magnitude: 8, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
        }
      });
      break;

    case 'footerText':
      requests.push({
        updateTextStyle: {
          range: r,
          textStyle: {
            fontSize: { magnitude: 10, unit: 'PT' },
            foregroundColor: { color: { rgbColor: colors.lightGray } },
            weightedFontFamily: { fontFamily: 'Open Sans', weight: 400 }
          },
          fields: 'fontSize,foregroundColor,weightedFontFamily'
        }
      });
      requests.push({
        updateParagraphStyle: {
          range: r,
          paragraphStyle: { 
            alignment: 'CENTER',
            lineSpacing: 100,
            spaceAbove: { magnitude: 20, unit: 'PT' }
          },
          fields: 'alignment,lineSpacing,spaceAbove'
        }
      });
      break;
  }
}

return [{ json: { docId, requests } }];

const docId = $('Create Google Doc').first().json.documentId;
const docBody = $json.body;
const tables = $('Prepare Document').first().json.tables || [];

if (!tables.length || !docBody || !docBody.content) {
  return [{ json: { docId, requests: [], hasTables: false } }];
}

// Find placeholder positions in document
const placeholders = [];

for (const elem of docBody.content) {
  if (elem.paragraph && elem.paragraph.elements) {
    for (const el of elem.paragraph.elements) {
      if (el.textRun && el.textRun.content) {
        const text = el.textRun.content;
        const regex = /\{\{TBL:(\d+)\}\}/g;
        let match;
        while ((match = regex.exec(text)) !== null) {
          const tableIdx = parseInt(match[1]);
          placeholders.push({
            tableIdx,
            startIndex: el.startIndex + match.index,
            endIndex: el.startIndex + match.index + match[0].length,
            paraStartIndex: elem.startIndex,
            paraEndIndex: elem.endIndex
          });
        }
      }
    }
  }
}

if (!placeholders.length) {
  return [{ json: { docId, requests: [], hasTables: false } }];
}

// Sort from last to first (by position, descending)
placeholders.sort((a, b) => b.startIndex - a.startIndex);

const requests = [];

// Track table positions for later formatting
const tablePositions = [];

for (const ph of placeholders) {
  const table = tables.find(t => t.index === ph.tableIdx);
  if (!table) continue;

  const totalRows = 1 + table.rows.length; // header + data rows
  const totalCols = table.headers.length;

  if (totalCols === 0) continue;

  // 1. Delete the entire paragraph containing the placeholder
  // (includes the placeholder text and its newline)
  requests.push({
    deleteContentRange: {
      range: {
        startIndex: ph.paraStartIndex,
        endIndex: ph.paraEndIndex
      }
    }
  });

  // 2. Insert table at the paragraph start position
  const tableInsertPos = ph.paraStartIndex;
  requests.push({
    insertTable: {
      rows: totalRows,
      columns: totalCols,
      location: {
        index: tableInsertPos
      }
    }
  });

  // 3. Populate cells from LAST to FIRST
  // For a newly inserted empty table at index S with C columns:
  // Google Docs table structure: table+row0 share index S,
  // cell starts at S+1, paragraph (text insertion) at S+2.
  // Each cell = 2 indices (cell start + paragraph). Row separator = 1 index.
  // Cell(r, c) text insertion index = S + 2 + r * (1 + 2 * C) + c * 2
  const allCells = [];

  // Header row (row 0)
  for (let c = 0; c < totalCols; c++) {
    allCells.push({ r: 0, c: c, text: String(table.headers[c] || '') });
  }
  // Data rows
  for (let r = 0; r < table.rows.length; r++) {
    for (let c = 0; c < totalCols; c++) {
      allCells.push({ r: r + 1, c: c, text: String(table.rows[r]?.[c] ?? '') });
    }
  }

  // Sort from last cell to first cell
  allCells.sort((a, b) => {
    if (a.r !== b.r) return b.r - a.r;
    return b.c - a.c;
  });

  for (const cell of allCells) {
    if (cell.text) {
      const cellIndex = tableInsertPos + 2 + cell.r * (1 + 2 * totalCols) + cell.c * 2;
      requests.push({
        insertText: {
          location: { index: cellIndex },
          text: cell.text
        }
      });
    }
  }

  tablePositions.push({
    insertPos: tableInsertPos,
    totalRows,
    totalCols,
    headers: table.headers,
    rows: table.rows
  });
}

return [{ json: { docId, requests, hasTables: true, tablePositions } }];

const docId = $('Create Google Doc').first().json.documentId;
const docBody = $json.body;

if (!docBody || !docBody.content) {
  return [{ json: { docId, requests: [] } }];
}

const requests = [];

// Color palette matching the document theme
const colors = {
  navy: { red: 0.1, green: 0.15, blue: 0.3 },
  darkBlue: { red: 0.15, green: 0.25, blue: 0.45 },
  gold: { red: 0.75, green: 0.6, blue: 0.2 },
  white: { red: 1.0, green: 1.0, blue: 1.0 },
  lightGray: { red: 0.95, green: 0.96, blue: 0.97 },
  bodyText: { red: 0.15, green: 0.15, blue: 0.15 },
  borderColor: { red: 0.8, green: 0.82, blue: 0.85 }
};

const borderStyle = {
  width: { magnitude: 0.5, unit: 'PT' },
  color: { color: { rgbColor: colors.borderColor } },
  dashStyle: 'SOLID'
};

// Find all tables in the document
for (const elem of docBody.content) {
  if (elem.table) {
    const table = elem.table;
    const tableStartIndex = elem.startIndex;
    const tableEndIndex = elem.endIndex;
    const numRows = table.tableRows.length;
    const numCols = table.tableRows[0]?.tableCells?.length || 0;

    for (let r = 0; r < numRows; r++) {
      const row = table.tableRows[r];
      if (!row || !row.tableCells) continue;

      for (let c = 0; c < row.tableCells.length; c++) {
        const cell = row.tableCells[c];
        if (!cell) continue;

        const cellStart = cell.startIndex;
        const cellEnd = cell.endIndex;

        // Cell background color
        const isHeader = (r === 0);
        const isEvenRow = (r % 2 === 0);
        const bgColor = isHeader ? colors.navy : (isEvenRow ? colors.lightGray : colors.white);

        requests.push({
          updateTableCellStyle: {
            tableStartLocation: { index: tableStartIndex },
            tableCellLocation: {
              tableStartLocation: { index: tableStartIndex },
              rowIndex: r,
              columnIndex: c
            },
            tableCellStyle: {
              backgroundColor: { color: { rgbColor: bgColor } },
              paddingTop: { magnitude: 4, unit: 'PT' },
              paddingBottom: { magnitude: 4, unit: 'PT' },
              paddingLeft: { magnitude: 6, unit: 'PT' },
              paddingRight: { magnitude: 6, unit: 'PT' },
              borderTop: borderStyle,
              borderBottom: borderStyle,
              borderLeft: borderStyle,
              borderRight: borderStyle
            },
            fields: 'backgroundColor,paddingTop,paddingBottom,paddingLeft,paddingRight,borderTop,borderBottom,borderLeft,borderRight'
          }
        });

        // Text formatting for cell content
        if (cell.content) {
          for (const cellElem of cell.content) {
            if (cellElem.paragraph && cellElem.paragraph.elements) {
              for (const textEl of cellElem.paragraph.elements) {
                if (textEl.textRun && textEl.startIndex !== undefined) {
                  const textStart = textEl.startIndex;
                  const textEnd = textEl.endIndex;

                  if (textStart < textEnd) {
                    requests.push({
                      updateTextStyle: {
                        range: { startIndex: textStart, endIndex: textEnd },
                        textStyle: {
                          bold: isHeader,
                          fontSize: { magnitude: isHeader ? 10 : 9.5, unit: 'PT' },
                          foregroundColor: {
                            color: { rgbColor: isHeader ? colors.white : colors.bodyText }
                          },
                          weightedFontFamily: {
                            fontFamily: isHeader ? 'Montserrat' : 'Open Sans',
                            weight: isHeader ? 600 : 400
                          }
                        },
                        fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
                      }
                    });

                    // Paragraph alignment
                    requests.push({
                      updateParagraphStyle: {
                        range: { startIndex: textStart, endIndex: textEnd },
                        paragraphStyle: {
                          alignment: 'START',
                          lineSpacing: 115,
                          spaceAbove: { magnitude: 0, unit: 'PT' },
                          spaceBelow: { magnitude: 0, unit: 'PT' }
                        },
                        fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
                      }
                    });
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

return [{ json: { docId, requests } }];
